const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Get Afghanistan boundary from LSIB 2017
  const afg = ee.FeatureCollection('USDOS/LSIB_SIMPLE/2017')
    .filter(ee.Filter.eq('country_na', 'Afghanistan'));
  const region = afg.geometry();

  // Date ranges for February
  const feb2017 = ee.DateRange('2017-02-01', '2017-02-28');
  const feb2018 = ee.DateRange('2018-02-01', '2018-02-28');

  // Function to get and process LST for a date range
  function getLST(dateRange, product) {
    let col = ee.ImageCollection(product)
      .filterBounds(region)
      .filterDate(dateRange.start(), dateRange.end());

    // Map to convert LST to Celsius and mask poor quality
    col = col.map(function(img) {
      // Get QC band and extract bits 0-1 (LST quality)
      const qc = img.select('QC_Day');
      const quality = qc.bitwiseAnd(3); // bits 0-1
      const mask = quality.lt(2); // 0=good, 1=acceptable, 2/3=bad
      // Convert LST from Kelvin to Celsius: scale 0.02, offset -273.15
      const lst = img.select('LST_Day_1km')
        .multiply(0.02)
        .subtract(273.15)
        .updateMask(mask)
        .rename('LST_C');
      return lst.copyProperties(img, ['system:time_start']);
    });

    // Mean composite for the period
    const meanImg = col.mean().clip(region);
    return {collection: col, image: meanImg};
  }

  // 2. Data Acquisition & Check
  // Try MODIS Terra first, fallback to Aqua if no data
  function tryProducts(dateRange, year) {
    let result = getLST(dateRange, 'MODIS/006/MOD11A1');
    let colSize = result.collection.size().getInfo();
    let productName = 'Terra';
    if (colSize === 0) {
      result = getLST(dateRange, 'MODIS/006/MYD11A1');
      colSize = result.collection.size().getInfo();
      productName = 'Aqua';
    }
    console.log(`${year} Images: ${colSize} (Product: ${productName})`);
    if (colSize === 0) {
      return null;
    }
    return result.image;
  }

  const img2017 = tryProducts(feb2017, '2017');
  const img2018 = tryProducts(feb2018, '2018');

  // Check for empty collections (C1)
  if (!img2017 || !img2018) {
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Processing - get pixel counts and mean LST
  function computeStats(img, label) {
    const stats = img.reduceRegion({
      reducer: ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
      }),
      geometry: region,
      scale: 1000,
      maxPixels: 1e9,
      bestEffort: true
    });
    const mean = stats.get('LST_C').getInfo();
    const count = stats.get('LST_C_count').getInfo();
    console.log(`${label} - Mean LST: ${mean !== null ? mean.toFixed(2) : 'null'}°C, Valid Pixels: ${count}`);
    return {mean, count};
  }

  const stats2017 = computeStats(img2017, '2017');
  const stats2018 = computeStats(img2018, '2018');

  // Check for no valid pixels (C2)
  if (stats2017.count === 0 || stats2018.count === 0) {
    console.log('<answer>C2</answer>');
    return;
  }

  // 4. Validation & Final Answer
  // Check for invalid values (C3)
  if (stats2017.mean === null || stats2018.mean === null ||
      isNaN(stats2017.mean) || isNaN(stats2018.mean)) {
    console.log('<answer>C3</answer>');
    return;
  }

  // Reasonable LST range check for Afghanistan in February
  if (stats2017.mean < -50 || stats2017.mean > 50 ||
      stats2018.mean < -50 || stats2018.mean > 50) {
    console.log('Warning: LST out of expected range.');
  }

  // Determine answer
  const increase = stats2018.mean > stats2017.mean;
  console.log(`Change: ${stats2018.mean - stats2017.mean:.2f}°C`);

  if (increase) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
